import{_ as t,H as n,f as a,i}from"./chunks/framework.B05LFaXs.js";const s="/cass-editor/docs/assets/welcome-page.MBSreiLl.png",r="/cass-editor/docs/assets/expand-menu-button.BztEnkRv.png",l="/cass-editor/docs/assets/expanded-menu.XagoZ0qq.png",c="/cass-editor/docs/assets/collapse-menu-button.BR56dAF7.png",g="/cass-editor/docs/assets/collapsed-menu.CYWcgrN-.png",o="/cass-editor/docs/assets/login-button.Ca1IXWEB.png",u="/cass-editor/docs/assets/create-account-button.i3fYEXkC.png",p="/cass-editor/docs/assets/create-account-submit-button.CFOcYJh4.png",m="/cass-editor/docs/assets/helpful-links.EKkT7Kzk.png",S=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/getting-started/index.md","filePath":"authoring/getting-started/README.md"}'),h={name:"authoring/getting-started/index.md"};function d(f,e,b,w,k,C){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Welcome to the documentation for <strong>CaSS Authoring Tools</strong> - an open source collaborative interface for authoring and managing competency frameworks.</p><ul><li><strong>Collaborate with your team</strong><ul><li>CaSS Authoring Tools supports user and group access to your authored competency frameworks.</li></ul></li><li><strong>Customized Competency Properties</strong><ul><li>Our Authoring Tools support your organization&#39;s unique needs. Use our custom competency properties to customize the abilities of the authoring tool.</li></ul></li><li><strong>Work with existing frameworks</strong><ul><li>CaSS can import and export a variety of file format and types. Start working with your existing data.</li></ul></li></ul><p>This document details the functionality of CaSS Authoring Tools and includes detailed instructions for use. If you are looking for help with a specific function of CaSS Authoring Tools, you can navigate to the appropriate section by using the table of contents above. A list of helpful resources and links is also included at the end of this page.</p><h2 id="welcome-screen" tabindex="-1">Welcome Screen <a class="header-anchor" href="#welcome-screen" aria-label="Permalink to &quot;Welcome Screen&quot;">​</a></h2><p>When first visiting CaSS Authoring Tools, you will be presented with the <strong>Welcome Screen</strong> which offers simple instructions for getting started. More detailed instructions on how CaSS Authoring Tools can be used are included in this User Guide.</p><p><img src="'+s+'" alt="Welcome Page"></p><h2 id="application-navigation-menu" tabindex="-1">Application Navigation Menu <a class="header-anchor" href="#application-navigation-menu" aria-label="Permalink to &quot;Application Navigation Menu&quot;">​</a></h2><p>The CaSS Authoring Tool navigation menu is used to access the different functionality modules within the application.  It can be viewed and used in two specific ways.</p><h3 id="expanded-navigation-menu" tabindex="-1">Expanded Navigation Menu <a class="header-anchor" href="#expanded-navigation-menu" aria-label="Permalink to &quot;Expanded Navigation Menu&quot;">​</a></h3><p>The expanded navigation menu can be accessed by clicking on the expand menu icon on the top right corner of the screen.</p><p><img src="'+r+'" alt="Expand Menu Button"></p><p><img src="'+l+'" alt="Expanded Menu"></p><p>Once expanded, the navigation menu displays links to the following application areas:</p><ul><li><strong>Application Login</strong>  - Login to the application</li><li><strong>Create New</strong> - Dropdown menu for creating a new Framework, Directory, or Taxonomy</li><li><strong>Competencies &amp; Frameworks</strong><ul><li><em>Frameworks</em> - Competency framework search</li><li><em>Import</em> - Import of competency frameworks</li><li><em>Crosswalk Frameworks</em> - Dual competency framework alignment/relationships</li><li><em>Documentation</em> - This CaSS Authoring Tools User Guide</li></ul></li><li><strong>My Directories</strong><ul><li>A list of Directories that you have access to</li></ul></li><li><strong>Taxonomy</strong><ul><li><em>Taxonomies</em> - Taxonomy search</li><li><em>Import</em> - Import of taxonomies</li><li><em>Documentation</em> - This CaSS Authoring Tools User Guide</li></ul></li><li><strong>Configuration</strong><ul><li><em>Configurations</em> - Configuration management</li><li><em>Plugins</em> - Plugin management</li></ul></li><li><strong>Users and Groups</strong> - User group management (<em>this option only appears if you are logged into the application</em>)</li></ul><h3 id="collapsed-navigation-menu" tabindex="-1">Collapsed Navigation Menu <a class="header-anchor" href="#collapsed-navigation-menu" aria-label="Permalink to &quot;Collapsed Navigation Menu&quot;">​</a></h3><p><img src="'+c+'" alt="Collapse Menu"></p><p>The navigation menu can be collapsed by clicking on the collapse menu icon on the upper right hand corner of the expanded navigation menu.</p><p><img src="'+g+'" alt="Collapsed Menu"></p><p>Once collapsed, the navigation menu displays links to the following application areas:</p><ul><li><strong>Application Login</strong> - Login to the application</li><li><strong>Frameworks</strong> - Competency framework search</li><li><strong>Crosswalk Frameworks</strong> - Dual competency framework alignment/relationships</li><li><strong>Directories</strong> - Direcotires available to user</li><li><strong>Taxonomies</strong> - Taxonomy search</li><li><strong>Configurations</strong> - Configuration management</li><li><strong>Plugins</strong> - Plugin management</li><li><strong>Users and Groups</strong> - User group management (<em>this option only appears if you are logged into the application</em>)</li></ul><h2 id="application-login" tabindex="-1">Application Login <a class="header-anchor" href="#application-login" aria-label="Permalink to &quot;Application Login&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Note</p><p>This section is not applicable to Credential Engine instances of CAT.</p></div><p>By default, most CAT functionality is available without being logged in. You can search for, create, and manage public frameworks, competencies, and other CaSS data. Some tools, however, will not be available until after going through the login process. Accessing secure CaSS data, securing your own CaSS data, and explicitly granting access and permissions to owned data all requires you to be logged into the environment. More details about managing user groups and data permissions can be found in the corresponding sections.</p><p>The <em><strong>login button</strong></em> can be accessed through the application navigation menu.</p><p><img src="'+o+'" alt="CAT Navigation Menu - Login Button"></p><h2 id="creating-an-account" tabindex="-1">Creating an Account <a class="header-anchor" href="#creating-an-account" aria-label="Permalink to &quot;Creating an Account&quot;">​</a></h2><p>From the landing page users have the option to login or create a new account to access the CaSS Authoring Tool. At the login page users have the option to select <em><strong>create account</strong></em> shown below.</p><p><img src="'+u+'" alt="CAT Login - Create Account Button"></p><p>From here, users will be prompted to input basic information required to register their account with the CaSS Authoring Tool.</p><p>Once users have successfully entered the required information, they can hit <em><strong>create</strong></em> to begin the registration of their account. Once successfully registered, you will be automatically logged into the application.</p><p><img src="'+p+'" alt="CAT Login - Create Account Submit Button"></p><h3 id="logging-into-an-existing-account" tabindex="-1">Logging into an Existing Account <a class="header-anchor" href="#logging-into-an-existing-account" aria-label="Permalink to &quot;Logging into an Existing Account&quot;">​</a></h3><p>You can login with existing accounts by filling out the appropriate fields on the login form and clicking the <em><strong>login</strong></em> button.</p><p><img src="'+o+'" alt="CAT Login - Login Button"></p><h2 id="helpful-links" tabindex="-1">Helpful Links <a class="header-anchor" href="#helpful-links" aria-label="Permalink to &quot;Helpful Links&quot;">​</a></h2><p>On the right side bar of the CaSS Authoring Tools welcome page you will find a list of documentation, resources, example framework imports, options for getting in touch with the CaSS community, and legacy applications of CaSS.</p><p><img src="'+m+'" alt="CAT Welcome - Helpful Links "></p><h2 id="get-in-touch" tabindex="-1">Get in touch <a class="header-anchor" href="#get-in-touch" aria-label="Permalink to &quot;Get in touch&quot;">​</a></h2><ul><li><a href="https://www.google.com/url?q=https://docs.google.com/a/eduworks.com/forms/viewform?bc%3Dtransparent%26embedded%3Dtrue%26f%3DArial%25252C%252BVerdana%25252C%252Bsans-serif%26hl%3Den%26htc%3D%252523666666%26id%3D1BMaboapV0IaS8iGnCJut2obPZ9y3CWkxXuvy-7krcgE%26lc%3D%252523003965%26pli%3D1%26tc%3D%252523444444%26ttl%3D0&amp;sa=D&amp;ust=1603207897946000&amp;usg=AOvVaw3DXisffX2tTcQQH_sM4J67" target="_blank" rel="noreferrer">Join the Slack Channel</a></li><li><a href="mailto:cass@eduworks.com" target="_blank" rel="noreferrer">Email us</a></li></ul>',41)])])}const x=t(h,[["render",d]]);export{S as __pageData,x as default};
